// Shared HttpClient instance for making HTTP requests (best practice for reuse)
private static readonly HttpClient _client = new HttpClient();
/// <summary>
/// Fetches data from an API with retry mechanism and timeout functionality
/// </summary>
/// <param name="apiUrl">The URL to fetch data from</param>
/// <param name="cancellationToken">Token to cancel the operation</param>
/// <param name="maxRetries">Maximum number of retry attempts</param>
/// <param name="cancellationDelay">Timeout duration in milliseconds</param>
/// <param name="statusLabel">UI label to show status updates</param>
public async Task<string> FetchDataFromApiWithRetryAsync(string apiUrl, CancellationToken cancellationToken, int maxRetries, int cancellationDelay, Label statusLabel)
{
var retryCount = 0;
// Create a linked cancellation token that combines user cancellation and timeout
using var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
while (retryCount < maxRetries)
{
try
{
// Set timeout for this attempt
cts.CancelAfter(cancellationDelay);
return await FetchDataFromApiAsync(cts.Token, statusLabel);
}
catch (Exception ex) when (!(ex is OperationCanceledException))
{
// If not the last retry attempt, implement exponential backoff
if (retryCount < maxRetries - 1) {
retryCount++;
// Exponential backoff: 2^retryCount seconds (1s, 2s, 4s, 8s, etc.)
int delay = (int)Math.Pow(2, retryCount) * 1000;
await Task.Delay(delay, cancellationToken);
UpdateStatusLabel($"Retrying ({retryCount}/{maxRetries})...", statusLabel);
} else {
// If all retries failed, throw exception with details
throw new Exception($"Failed to fetch data after {maxRetries} retries: {ex.Message}", ex);
}
}
}
// This is reached if maxRetries is 0 or some other unexpected case
throw new OperationCanceledException("The operation was cancelled.", cts.Token);
}
/// <summary>
/// Makes the actual API call to fetch data
/// </summary>
private async Task<string> FetchDataFromApiAsync(string apiUrl, CancellationToken cancellationToken, Label statusLabel)
{
UpdateStatusLabel("Fetching data...", statusLabel);
// Perform HTTP GET request with cancellation support
HttpResponseMessage response = await _client.GetAsync(apiUrl, cancellationToken);
response.EnsureSuccessStatusCode(); // Throws if response is not successful
string data = await response.Content.ReadAsStringAsync();
UpdateStatusLabel("Data fetched.", statusLabel);
return data;
}
/// <summary>
/// Updates UI label text safely across threads
/// </summary>
/// <param name="message">The message to display</param>
/// <param name="statusLabel">The label control to update</param>
private void UpdateStatusLabel(string message, Label statusLabel)
{
// Check if we need to invoke on UI thread
if (statusLabel.InvokeRequired) {
// Use BeginInvoke to update label on UI thread
statusLabel.BeginInvoke(new Action<string, Label>(UpdateStatusLabel), message, statusLabel);
} else {
// Direct update if already on UI thread
statusLabel.Text = message;
}
}

Appendix
This is additional information for Visual Studio Code tasks.
Schema for tasks.json
The following interfaces define the basic schema of the tasks.json
file.
Note: Some task options are contributed by VS Code extensions. You can use
tasks.json
IntelliSense to find a complete list, using the Trigger Suggestions command (⌃Space (Windows, Linux Ctrl+Space)).
interface TaskConfiguration extends BaseTaskConfiguration {
/**
* The configuration's version number
*/
version: '2.0.0';
/**
* Windows specific task configuration
*/
windows?: BaseTaskConfiguration;
/**
* macOS specific task configuration
*/
osx?: BaseTaskConfiguration;
/**
* Linux specific task configuration
*/
linux?: BaseTaskConfiguration;
}
interface BaseTaskConfiguration {
/**
* The type of a custom task. Tasks of type "shell" are executed
* inside a shell (e.g. bash, cmd, powershell, ...)
*/
type: 'shell' | 'process';
/**
* The command to be executed. Can be an external program or a shell
* command.
*/
command: string;
/**
* Specifies whether a global command is a background task.
*/
isBackground?: boolean;
/**
* The command options used when the command is executed. Can be omitted.
*/
options?: CommandOptions;
/**
* The arguments passed to the command. Can be omitted.
*/
args?: string[];
/**
* The presentation options.
*/
presentation?: PresentationOptions;
/**
* The problem matcher to be used if a global command is executed (e.g. no tasks
* are defined). A tasks.json file can either contain a global problemMatcher
* property or a tasks property but not both.
*/
problemMatcher?: string | ProblemMatcher | (string | ProblemMatcher)[];
/**
* The configuration of the available tasks. A tasks.json file can either
* contain a global problemMatcher property or a tasks property but not both.
*/
tasks?: TaskDescription[];
}
/**
* Options to be passed to the external program or shell
*/
export interface CommandOptions {
/**
* The current working directory of the executed program or shell.
* If omitted the current workspace's root is used.
*/
cwd?: string;
/**
* The environment of the executed program or shell. If omitted
* the parent process' environment is used.
*/
env?: { [key: string]: string };
/**
* Configuration of the shell when task type is `shell`
*/
shell: {
/**
* The shell to use.
*/
executable: string;
/**
* The arguments to be passed to the shell executable to run in command mode
* (e.g ['-c'] for bash or ['/S', '/C'] for cmd.exe).
*/
args?: string[];
};
}
/**
* The description of a task.
*/
interface TaskDescription {
/**
* The task's name
*/
label: string;
/**
* The type of a custom task. Tasks of type "shell" are executed
* inside a shell (e.g. bash, cmd, powershell, ...)
*/
type: 'shell' | 'process';
/**
* The command to execute. If the type is "shell" it should be the full
* command line including any additional arguments passed to the command.
*/
command: string;
/**
* Whether the executed command is kept alive and runs in the background.
*/
isBackground?: boolean;
/**
* Additional arguments passed to the command. Should be used if type
* is "process".
*/
args?: string[];
/**
* Defines the group to which this task belongs. Also supports to mark
* a task as the default task in a group.
*/
group?: 'build' | 'test' | { kind: 'build' | 'test'; isDefault: boolean };
/**
* The presentation options.
*/
presentation?: PresentationOptions;
/**
* The problem matcher(s) to use to capture problems in the tasks
* output.
*/
problemMatcher?: string | ProblemMatcher | (string | ProblemMatcher)[];
/**
* Defines when and how a task is run.
*/
runOptions?: RunOptions;
}
interface PresentationOptions {
/**
* Controls whether the task output is reveal in the user interface.
* Defaults to `always`.
*/
reveal?: 'never' | 'silent' | 'always';
/**
* Controls whether the command associated with the task is echoed
* in the user interface. Defaults to `true`.
*/
echo?: boolean;
/**
* Controls whether the panel showing the task output is taking focus.
* Defaults to `false`.
*/
focus?: boolean;
/**
* Controls if the task panel is used for this task only (dedicated),
* shared between tasks (shared) or if a new panel is created on
* every task execution (new). Defaults to `shared`.
*/
panel?: 'shared' | 'dedicated' | 'new';
/**
* Controls whether to show the `Terminal will be reused by tasks,
* press any key to close it` message.
*/
showReuseMessage?: boolean;
/**
* Controls whether the terminal is cleared before this task is run.
* Defaults to `false`.
*/
clear?: boolean;
/**
* Controls whether the task is executed in a specific terminal
* group using split panes. Tasks in the same group (specified by a string value)
* will use split terminals to present instead of a new terminal panel.
*/
group?: string;
}
/**
* A description of a problem matcher that detects problems
* in build output.
*/
interface ProblemMatcher {
/**
* The name of a base problem matcher to use. If specified the
* base problem matcher will be used as a template and properties
* specified here will replace properties of the base problem
* matcher
*/
base?: string;
/**
* The owner of the produced VS Code problem. This is typically
* the identifier of a VS Code language service if the problems are
* to be merged with the one produced by the language service
* or 'external'. Defaults to 'external' if omitted.
*/
owner?: string;
/**
* A human-readable string describing the source of this problem.
* E.g. 'typescript' or 'super lint'.
*/
source?: string;
/**
* The severity of the VS Code problem produced by this problem matcher.
*
* Valid values are:
* "error": to produce errors.
* "warning": to produce warnings.
* "info": to produce infos.
*
* The value is used if a pattern doesn't specify a severity match group.
* Defaults to "error" if omitted.
*/
severity?: string;
/**
* Defines how filename reported in a problem pattern
* should be read. Valid values are:
* - "absolute": the filename is always treated absolute.
* - "relative": the filename is always treated relative to
* the current working directory. This is the default.
* - ["relative", "path value"]: the filename is always
* treated relative to the given path value.
* - "autodetect": the filename is treated relative to
* the current workspace directory, and if the file
* does not exist, it is treated as absolute.
* - ["autodetect", "path value"]: the filename is treated
* relative to the given path value, and if it does not
* exist, it is treated as absolute.
* - "search": performs a deep (and, possibly, heavy) file system
* search within the directories.
* - ["search", {include: ["${workspaceFolder}"]}]: performs
* a deep search among the directories given in the "include" array.
* - ["search", {include: ["${workspaceFolder}"], exclude: []}]:
* performs a deep search among the directories given in the "include"
* array, excluding those named in the "exclude" array.
*/
fileLocation?: string | string[] | ['search', { include?: string[]; exclude?: string[] }];
/**
* The name of a predefined problem pattern, the inline definition
* of a problem pattern or an array of problem patterns to match
* problems spread over multiple lines.
*/
pattern?: string | ProblemPattern | ProblemPattern[];
/**
* Additional information used to detect when a background task (like a watching task in Gulp)
* is active.
*/
background?: BackgroundMatcher;
}
/**
* A description to track the start and end of a background task.
*/
interface BackgroundMatcher {
/**
* If set to true the watcher is in active mode when the task
* starts. This is equals of issuing a line that matches the
* beginPattern.
*/
activeOnStart?: boolean;
/**
* If matched in the output the start of a background task is signaled.
*/
beginsPattern?: string;
/**
* If matched in the output the end of a background task is signaled.
*/
endsPattern?: string;
}
interface ProblemPattern {
/**
* The regular expression to find a problem in the console output of an
* executed task.
*/
regexp: string;
/**
* Whether the pattern matches a problem for the whole file or for a location
* inside a file.
*
* Defaults to "location".
*/
kind?: 'file' | 'location';
/**
* The match group index of the filename.
*/
file: number;
/**
* The match group index of the problem's location. Valid location
* patterns are: (line), (line,column) and (startLine,startColumn,endLine,endColumn).
* If omitted the line and column properties are used.
*/
location?: number;
/**
* The match group index of the problem's line in the source file.
* Can only be omitted if location is specified.
*/
line?: number;
/**
* The match group index of the problem's column in the source file.
*/
column?: number;
/**
* The match group index of the problem's end line in the source file.
*
* Defaults to undefined. No end line is captured.
*/
endLine?: number;
/**
* The match group index of the problem's end column in the source file.
*
* Defaults to undefined. No end column is captured.
*/
endColumn?: number;
/**
* The match group index of the problem's severity.
*
* Defaults to undefined. In this case the problem matcher's severity
* is used.
*/
severity?: number;
/**
* The match group index of the problem's code.
*
* Defaults to undefined. No code is captured.
*/
code?: number;
/**
* The match group index of the message. Defaults to 0.
*/
message: number;
/**
* Specifies if the last pattern in a multi line problem matcher should
* loop as long as it does match a line consequently. Only valid on the
* last problem pattern in a multi line problem matcher.
*/
loop?: boolean;
}
/**
* A description to when and how run a task.
*/
interface RunOptions {
/**
* Controls how variables are evaluated when a task is executed through
* the Rerun Last Task command.
* The default is `true`, meaning that variables will be re-evaluated when
* a task is rerun. When set to `false`, the resolved variable values from
* the previous run of the task will be used.
*/
reevaluateOnRerun?: boolean;
/**
* Specifies when a task is run.
*
* Valid values are:
* "default": The task will only be run when executed through the Run Task command.
* "folderOpen": The task will be run when the containing folder is opened.
*/
runOn?: string;
}

File Icon Theme
Visual Studio Code displays icons next to filenames throughout its UI, and extensions can contribute new sets of file icons that users can choose from.
Adding a new File Icon Theme
You can create your own file icon theme from icons (preferably SVG) and from icon fonts. As example, check out the two built-in themes: Minimal and Seti.
To begin, create a VS Code extension and add the iconTheme
contribution point.
{
"contributes": {
"iconThemes": [
{
"id": "turtles",
"label": "Turtles",
"path": "./fileicons/turtles-icon-theme.json"
}
]
}
}
The id
is the identifier for the icon theme. It is used as an identifier in the settings, so make it unique but also readable. label
is shown in the file icon theme picker dropdown. The path
points to a file in the extension that defines the icon set. If your icon set name follows the *icon-theme.json
name scheme, you will get completion support and hovers in VS Code.
File Icon Set File
The file icon set file is a JSON file consisting of file icon associations and icon definitions.
An icon association maps a file type ('file', 'folder', 'json-file'...) to an icon definition. Icon definitions define where the icon is located: That can be an image file or also glyph in a font.
Icon definitions
The iconDefinitions
section contains all definitions. Each definition has an id, which will be used to reference the definition. A definition can be referenced also by more than one file association.
{
"iconDefinitions": {
"_folder_dark": {
"iconPath": "./images/Folder_16x_inverse.svg"
}
}
}
This icon definition above contains a definition with the identifier _folder_dark
.
The following properties are supported:
iconPath
: When using a svg/png: the path to the image.fontCharacter
: When using a glyph font: The character in the font to use.fontColor
: When using a glyph font: The color to use for the glyph.fontSize
: When using a font: The font size. By default, the size specified in the font specification is used. Should be a relative size (e.g. 150%) to the parent font size.fontId
: When using a font: The id of the font. If not specified, the first font specified in font specification section will be picked.
File association
Icons can be associated to folders, folder names, files, file extensions, file names and language IDs.
Additionally each of these associations can be refined for 'light' and 'highContrast' color themes.
Each file association points to an icon definition.
{
"file": "_file_dark",
"folder": "_folder_dark",
"folderExpanded": "_folder_open_dark",
"folderNames": {
".vscode": "_vscode_folder"
},
"fileExtensions": {
"ini": "_ini_file"
},
"fileNames": {
"win.ini": "_win_ini_file"
},
"languageIds": {
"ini": "_ini_file"
},
"light": {
"folderExpanded": "_folder_open_light",
"folder": "_folder_light",
"file": "_file_light",
"fileExtensions": {
"ini": "_ini_file_light"
}
},
"highContrast": {}
}
file
is the default file icon, shown for all files that don't match any extension, filename or language ID. Currently all properties defined by the definition of the file icon will be inherited (only relevant for font glyphs, useful for the fontSize).folder
is the folder icon for collapsed folders, and iffolderExpanded
is not set, also for expanded folders. Icons for specific folder names can be associated using thefolderNames
property. The folder icon is optional. If not set, no icon will be shown for folder.folderExpanded
is the folder icon for expanded folders. The expanded folder icon is optional. If not set, the icon defined forfolder
will be shown.folderNames
associates folder names to icons. The key of the set is the folder name, optionally prefixed by a single parent path segment (*). Patterns or wildcards are not supported. Folder name matching is case insensitive.folderNamesExpanded
associates folder names to icons for expanded folder. The key of the set is the folder name, optionally prefixed by a single parent path segment (*). Patterns or wildcards are not supported. Folder name matching is case insensitive.rootFolder
is the folder icon for collapsed workspace root folders , and ifrootFolderExpanded
is not set, also for expanded workspace root folders. If not set, the icon defined forfolder
will be shown for workspace root folders.rootFolderExpanded
is the folder icon for expanded workspace root folders. If not set, the icon defined forrootFolder
will be shown for expanded workspace root folders.rootFolderNames
associates root folder names to icons. The key of the set is the folder name. Patterns or wildcards are not supported. Root folder name matching is case insensitive.rootFolderNamesExpanded
associates root folder names to icons for expanded folder. The key of the set is the folder name. Patterns or wildcards are not supported. Root folder name matching is case insensitive.languageIds
associates languages to icons. The key in the set is the language ID as defined in the language contribution point. The language of a file is evaluated based on the file extensions and file names as defined in the language contribution. Note that the 'first line match' of the language contribution is not considered.fileExtensions
associates file extensions to icons. The key in the set is the file extension name. The extension name is a file name segment after a dot (not including the dot). File names with multiple dots such aslib.d.ts
can match multiple extensions; 'd.ts' and 'ts'. Optionally, the file extension name can be prefixed by a single parent path segment (*). Extensions are compared case insensitive.fileNames
associates file names to icons. The key in the set is the full file name, not including any path segments. Optionally, the file extension name can be prefixed by a single parent path segment (*). Patterns or wildcards are not supported. File name matching is case insensitive. A 'fileName' match is the strongest match, and the icon associated to the file name will be preferred over an icon of a matching fileExtension and also of a matching language ID.
(*) Some property keys (folderNames
, folderNamesExpanded
, fileExtensions
, fileNames
) can be prefixed by a single parent path segment. The icon will only be used if the resource's direct parent folder matches the parent path folder. This can be used to give resources in a particular folder (for example, system
) a different appearance:
"fileNames": {
"system/win.ini": "_win_ini_file"
},
system/win.ini
means that the association matches files called win.ini
directly in a folder system
"fileExtensions": {
"system/ini": "_ini_file"
},
system/ini
means that the association matches files called *.ini
directly in a folder system
A file extension match is preferred over a language match, but is weaker than a file name match. A match with a parent path segment is preferred over a match without such a segment of the same kind.
file name match with parent > file name match > file extension match with parent > file extension match > language match ...
The light
and the highContrast
section have the same file association properties as just listed. They allow to override icons for the corresponding themes.
Font definitions
The fonts
section lets you declare any number of glyph fonts that you want to use.
You can later reference these fonts in the icon definitions. The font declared first will be used as the default if an icon definition does not specify a font id.
Copy the font file into your extension and set the path accordingly. It is recommended to use WOFF fonts.
- Set 'woff' as the format.
- the weight property values are defined here.
- the style property values are defined here.
- the size should be relative to the font size where the icon is used. Therefore, always use percentage.
{
"fonts": [
{
"id": "turtles-font",
"src": [
{
"path": "./turtles.woff",
"format": "woff"
}
],
"weight": "normal",
"style": "normal",
"size": "150%"
}
],
"iconDefinitions": {
"_file": {
"fontCharacter": "\\E002",
"fontColor": "#5f8b3b",
"fontId": "turtles-font"
}
}
}
Folder icons in File Icon Themes
File Icon themes can instruct the File Explorer not to show the default folder icon (the rotating triangles or "twisties") when the folder icons are good enough to indicate the expansion state of a folder. This mode is enabled by setting "hidesExplorerArrows":true
in the File Icon theme definition file.
Language default icons
Language contributors can define an icon for the language.
{
"contributes": {
"languages": [
{
"id": "latex",
// ...
"icon": {
"light": "./icons/latex-light.png",
"dark": "./icons/latex-dark.png"
}
}
]
}
}
The icon is used if a file icon theme only has a generic file icon for the language.
Language default icons are only shown if:
- the file icon theme has specific file icons. E.g.
Minimal
does not have specific file icons and therefore does not use the language default icons - the file icon theme does not contain an icon for the given language, file extension or file name.
- the file icon theme does not define
"showLanguageModeIcons":false
Language default icons are always shown if
- the file icon theme does define
"showLanguageModeIcons":true

Notebook API
The Notebook API allows Visual Studio Code extensions to open files as notebooks, execute notebook code cells, and render notebook outputs in a variety of rich and interactive formats. You may know of popular notebook interfaces like Jupyter Notebook or Google Colab – the Notebook API allows for similar experiences inside Visual Studio Code.
Parts of a Notebook
A notebook consists of a sequence of cells and their outputs. The cells of a notebook can be either Markdown cells or code cells, and are rendered within the core of VS Code. The outputs can be of various formats. Some output formats, such as plain text, JSON, images, and HTML are rendered by VS Code core. Others, such as application-specific data or interactive applets, are rendered by extensions.
Cells in a notebook are read and written to the file system by a NotebookSerializer
, which handles reading data from the file system and converting it into a description of cells, as well as persisting modifications to the notebook back to the file system. The code cells of a notebook can be executed by a NotebookController
, which takes the contents of a cell and from it produces zero or more outputs in a variety of formats ranging from plain text to formatted documents or interactive applets. Application-specific output formats and interactive applet outputs are rendered by a NotebookRenderer
.
Visually:
Serializer
NotebookSerializer API Reference
A NotebookSerializer
is responsible for taking the serialized bytes of a notebook and deserializing those bytes into NotebookData
, which contains list of Markdown and code cells. It is responsible for the opposite conversion as well: taking NotebookData
and converting the data into serialized bytes to be saved.
Samples:
- JSON Notebook Serializer: Simple example notebook that takes JSON input and outputs prettified JSON in a custom
NotebookRenderer
. - Markdown Serializer: Open and edit Markdown files as a notebook.
Example
In this example, we build a simplified notebook provider extension for viewing files in the Jupyter Notebook format with a .notebook
extension (instead of its traditional file extension .ipynb
).
A notebook serializer is declared in package.json
under the contributes.notebooks
section as follows:
{
...
"contributes": {
...
"notebooks": [
{
"type": "my-notebook",
"displayName": "My Notebook",
"selector": [
{
"filenamePattern": "*.notebook"
}
]
}
]
}
}
The notebook serializer is then registered in the extension's activation event:
import { TextDecoder, TextEncoder } from 'util';
import * as vscode from 'vscode';
export function activate(context: vscode.ExtensionContext) {
context.subscriptions.push(
vscode.workspace.registerNotebookSerializer('my-notebook', new SampleSerializer())
);
}
interface RawNotebook {
cells: RawNotebookCell[];
}
interface RawNotebookCell {
source: string[];
cell_type: 'code' | 'markdown';
}
class SampleSerializer implements vscode.NotebookSerializer {
async deserializeNotebook(
content: Uint8Array,
_token: vscode.CancellationToken
): Promise<vscode.NotebookData> {
var contents = new TextDecoder().decode(content);
let raw: RawNotebookCell[];
try {
raw = (<RawNotebook>JSON.parse(contents)).cells;
} catch {
raw = [];
}
const cells = raw.map(
item =>
new vscode.NotebookCellData(
item.cell_type === 'code'
? vscode.NotebookCellKind.Code
: vscode.NotebookCellKind.Markup,
item.source.join('\n'),
item.cell_type === 'code' ? 'python' : 'markdown'
)
);
return new vscode.NotebookData(cells);
}
async serializeNotebook(
data: vscode.NotebookData,
_token: vscode.CancellationToken
): Promise<Uint8Array> {
let contents: RawNotebookCell[] = [];
for (const cell of data.cells) {
contents.push({
cell_type: cell.kind === vscode.NotebookCellKind.Code ? 'code' : 'markdown',
source: cell.value.split(/\r?\n/g)
});
}
return new TextEncoder().encode(JSON.stringify(contents));
}
}
Now try running your extension and opening a Jupyter Notebook formatted file saved with the .notebook
extension:
You should be able to open Jupyter-formatted notebooks and view their cells as both plain text and rendered Markdown, as well as edit the cells. However, outputs will not be persisted to disk; to save outputs you would need to also serialize and deserialize the outputs of cells from NotebookData
.
To run a cell, you will need to implement a NotebookController
.
Controller
NotebookController API Reference
A NotebookController
is responsible for taking a code cell and executing the code to produce some or no outputs.
A controller is directly associated with a notebook serializer and a type of notebook by setting the NotebookController#notebookType
property on creation of the controller. Then the controller is registered globally by pushing the controller onto the extension subscriptions on activate of the extension.
export function activate(context: vscode.ExtensionContext) {
context.subscriptions.push(new Controller());
}
class Controller {
readonly controllerId = 'my-notebook-controller-id';
readonly notebookType = 'my-notebook';
readonly label = 'My Notebook';
readonly supportedLanguages = ['python'];
private readonly _controller: vscode.NotebookController;
private _executionOrder = 0;
constructor() {
this._controller = vscode.notebooks.createNotebookController(
this.controllerId,
this.notebookType,
this.label
);
this._controller.supportedLanguages = this.supportedLanguages;
this._controller.supportsExecutionOrder = true;
this._controller.executeHandler = this._execute.bind(this);
}
private _execute(
cells: vscode.NotebookCell[],
_notebook: vscode.NotebookDocument,
_controller: vscode.NotebookController
): void {
for (let cell of cells) {
this._doExecution(cell);
}
}
private async _doExecution(cell: vscode.NotebookCell): Promise<void> {
const execution = this._controller.createNotebookCellExecution(cell);
execution.executionOrder = ++this._executionOrder;
execution.start(Date.now()); // Keep track of elapsed time to execute cell.
/* Do some execution here; not implemented */
execution.replaceOutput([
new vscode.NotebookCellOutput([
vscode.NotebookCellOutputItem.text('Dummy output text!')
])
]);
execution.end(true, Date.now());
}
}
If you're publishing a NotebookController
-providing extension separately from its serializer, then add an entry like notebookKernel<ViewTypeUpperCamelCased>
to the keywords
in its package.json
. For example, if you published an alternative kernel for the github-issues
notebook type, you should add a keyword notebookKernelGithubIssues
keyword to your extension.
This improves the discoverability of the extension when opening notebooks of the type <ViewTypeUpperCamelCased>
from within Visual Studio Code.
Samples:
- GitHub Issues Notebook: Controller to execute queries for GitHub Issues
- REST Book: Controller to run REST queries.
- Regexper notebooks: Controller to visualize regular expressions.
Output types
Outputs must be in one of three formats: Text Output, Error Output, or Rich Output. A kernel may provide multiple outputs for a single execution of a cell, in which case they will be displayed as a list.
Simple formats like Text Output, Error Output, or "simple" variants of Rich Output (HTML, Markdown, JSON, etc.) are rendered by VS Code core, whereas application specific Rich Output types are rendered by a NotebookRenderer. An extension may optionally choose to render "simple" Rich Outputs itself, for instance to add LaTeX support to Markdown outputs.
Text Output
Text outputs are the most simple output format, and work much like many REPLs you may be familiar with. They consist only of a text
field, which is rendered as plain text in the cell's output element:
vscode.NotebookCellOutputItem.text('This is the output...');
Error Output
Error outputs are helpful for displaying runtime errors in a consistent and understandable manner. They support standard Error
objects.
try {
/* Some code */
} catch (error) {
vscode.NotebookCellOutputItem.error(error);
}
Rich Output
Rich outputs are the most advanced form of displaying cell outputs. They allow for providing many different representations of the output data, keyed by mimetype. For example, if a cell output was to represent a GitHub Issue, the kernel might produce a rich output with several properties on its data
field:
- A
text/html
field containing a formatted view of the issue. - A
text/x-json
field containing a machine readable view. - An
application/github-issue
field that aNotebookRenderer
could use to create a fully interactive view of the issue.
In this case, the text/html
and text/x-json
views will be rendered by VS Code natively, but the application/github-issue
view will display an error if no NotebookRenderer
was registered to that mimetype.
execution.replaceOutput([new vscode.NotebookCellOutput([
vscode.NotebookCellOutputItem.text('<b>Hello</b> World', 'text/html'),
vscode.NotebookCellOutputItem.json({ hello: 'world' }),
vscode.NotebookCellOutputItem.json({ custom-data-for-custom-renderer: 'data' }, 'application/custom'),
])]);
By default, VS Code can render the following mimetypes:
- application/javascript
- text/html
- image/svg+xml
- text/markdown
- image/png
- image/jpeg
- text/plain
VS Code will render these mimetypes as code in a built-in editor:
- text/x-json
- text/x-javascript
- text/x-html
- text/x-rust
- ... text/x-LANGUAGE_ID for any other built-in or installed languages.
This notebook is using the built-in editor to display some Rust code:
To render an alternative mimetype, a NotebookRenderer
must be registered for that mimetype.
Notebook Renderer
A notebook renderer is responsible for taking output data of a specific mimetype and providing a rendered view of that data. A renderer shared by output cells can maintain global state between these cells. The complexity of the rendered view can range from simple static HTML to dynamic fully interactive applets. In this section, we'll explore various techniques for rendering an output representing a GitHub Issue.
You can get started quickly using boilerplate from our Yeoman generators. To do so, first install Yeoman and the VS Code Generators using:
npm install -g yo generator-code
Then, run yo code
and choose New Notebook Renderer (TypeScript)
.
If you don't use this template, you'll just want to make sure that you add notebookRenderer
to the keywords
in your extension's package.json
, and mention its mimetype somewhere in the extension name or description, so that users can find your renderer.
A Simple, Non-Interactive Renderer
Renderers are declared for a set of mimetypes by contributing to the contributes.notebookRenderer
property of an extension's package.json
. This renderer will work with input in the ms-vscode.github-issue-notebook/github-issue
format, which we will assume some installed controller is able to provide:
{
"activationEvents": ["...."],
"contributes": {
...
"notebookRenderer": [
{
"id": "github-issue-renderer",
"displayName": "GitHub Issue Renderer",
"entrypoint": "./out/renderer.js",
"mimeTypes": [
"ms-vscode.github-issue-notebook/github-issue"
]
}
]
}
}
Output renderers are always rendered in a single iframe
, separate from the rest of VS Code's UI, to ensure they don't accidentally interfere or cause slowdowns in VS Code. The contribution refers to an "entrypoint" script, which is loaded into the notebook's iframe
right before any output needs to be rendered. Your entrypoint needs to be a single file, which you can write yourself, or use a bundler like Webpack, Rollup, or Parcel to create.
When it's loaded, your entrypoint script should export ActivationFunction
from vscode-notebook-renderer
to render your UI once VS Code is ready to render your renderer. For example, this will put all your GitHub issue data as JSON into the cell output:
import type { ActivationFunction } from 'vscode-notebook-renderer';
export const activate: ActivationFunction = context => ({
renderOutputItem(data, element) {
element.innerText = JSON.stringify(data.json());
}
});
You can refer to the complete API definition here. If you're using TypeScript, you can install @types/vscode-notebook-renderer
and then add vscode-notebook-renderer
to the types
array in your tsconfig.json
to make these types available in your code.
To create richer content, you could manually create DOM elements, or use a framework like Preact and render it into the output element, for example:
import type { ActivationFunction } from 'vscode-notebook-renderer';
import { h, render } from 'preact';
const Issue: FunctionComponent<{ issue: GithubIssue }> = ({ issue }) => (
<div key={issue.number}>
<h2>
{issue.title}
(<a href={`https://github.com/${issue.repo}/issues/${issue.number}`}>#{issue.number}</a>)
</h2>
<img src={issue.user.avatar_url} style={{ float: 'left', width: 32, borderRadius: '50%', marginRight: 20 }} />
<i>@{issue.user.login}</i> Opened: <div style="margin-top: 10px">{issue.body}</div>
</div>
);
const GithubIssues: FunctionComponent<{ issues: GithubIssue[]; }> = ({ issues }) => (
<div>{issues.map(issue => <Issue key={issue.number} issue={issue} />)}</div>
);
export const activate: ActivationFunction = (context) => ({
renderOutputItem(data, element) {
render(<GithubIssues issues={data.json()} />, element);
}
});
Running this renderer on an output cell with a ms-vscode.github-issue-notebook/github-issue
data field gives us the following static HTML view:
If you have elements outside of the container or other asynchronous processes, you can use disposeOutputItem
to tear them down. This event will fire when output is cleared, a cell is deleted, and before new output is rendered for an existing cell. For example:
const intervals = new Map();
export const activate: ActivationFunction = (context) => ({
renderOutputItem(data, element) {
render(<GithubIssues issues={data.json()} />, element);
intervals.set(data.mime, setInterval(() => {
if(element.querySelector('h2')) {
element.querySelector('h2')!.style.color = `hsl(${Math.random() * 360}, 100%, 50%)`;
}
}, 1000));
},
disposeOutputItem(id) {
clearInterval(intervals.get(id));
intervals.delete(id);
}
});
It's important to bear in mind that all outputs for a notebook are rendered in different elements in the same iframe. If you use functions like document.querySelector
, make sure to scope it to the specific output you're interested in to avoid conflicting with other outputs. In this example, we use element.querySelector
to avoid that issue.
Interactive Notebooks (communicating with the controller)
Imagine we want to add the ability to view an issue's comments after clicking a button in the rendered output. Assuming a controller can provide issue data with comments under the ms-vscode.github-issue-notebook/github-issue-with-comments
mimetype, we might try to retrieve all the comments up front and implement it as follows:
const Issue: FunctionComponent<{ issue: GithubIssueWithComments }> = ({ issue }) => {
const [showComments, setShowComments] = useState(false);
return (
<div key={issue.number}>
<h2>
{issue.title}
(<a href={`https://github.com/${issue.repo}/issues/${issue.number}`}>#{issue.number}</a>)
</h2>
<img src={issue.user.avatar_url} style={{ float: 'left', width: 32, borderRadius: '50%', marginRight: 20 }} />
<i>@{issue.user.login}</i> Opened: <div style="margin-top: 10px">{issue.body}</div>
<button onClick={() => setShowComments(true)}>Show Comments</button>
{showComments && issue.comments.map(comment => <div>{comment.text}</div>)}
</div>
);
};
This immediately raises some flags. For one, we're loading full comment data for all issues, even before we've clicked the button. Additionally, we require controller support for a whole different mimetype even though we just want to show a bit more data.
Instead, the controller can provide additional functionality to the renderer by including a preload script which VS Code will load in the iframe as well. This script has access global functions postKernelMessage
and onDidReceiveKernelMessage
that can be used to communicate with the controller.
For example, you might modify your controller rendererScripts
to reference a new file where you create a connection back to the Extension Host, and expose a global communication script for the renderer to use.
In your controller:
class Controller {
// ...
readonly rendererScriptId = 'my-renderer-script';
constructor() {
// ...
this._controller.rendererScripts.push(
new vscode.NotebookRendererScript(
vscode.Uri.file(/* path to script */),
rendererScriptId
)
);
}
}
In your package.json
specify your script as a dependency of your renderer:
{
"activationEvents": ["...."],
"contributes": {
...
"notebookRenderer": [
{
"id": "github-issue-renderer",
"displayName": "GitHub Issue Renderer",
"entrypoint": "./out/renderer.js",
"mimeTypes": [...],
"dependencies": [
"my-renderer-script"
]
}
]
}
}
In your script file you can declare communication functions to communicate with the controller:
import 'vscode-notebook-renderer/preload';
globalThis.githubIssueCommentProvider = {
loadComments(issueId: string, callback: (comments: GithubComment[]) => void) {
postKernelMessage({ command: 'comments', issueId });
onDidReceiveKernelMessage(event => {
if (event.data.type === 'comments' && event.data.issueId === issueId) {
callback(event.data.comments);
}
});
}
};
And then you can consume that in the renderer. You want to make sure that you check whether the global exposed by the controller's render scripts is available, since other developers might create github issue output in other notebooks and controllers that don't implement the githubIssueCommentProvider
. In this case, we'll only show the Load Comments button if the global is available:
const canLoadComments = globalThis.githubIssueCommentProvider !== undefined;
const Issue: FunctionComponent<{ issue: GithubIssue }> = ({ issue }) => {
const [comments, setComments] = useState([]);
const loadComments = () =>
globalThis.githubIssueCommentProvider.loadComments(issue.id, setComments);
return (
<div key={issue.number}>
<h2>
{issue.title}
(<a href={`https://github.com/${issue.repo}/issues/${issue.number}`}>#{issue.number}</a>)
</h2>
<img src={issue.user.avatar_url} style={{ float: 'left', width: 32, borderRadius: '50%', marginRight: 20 }} />
<i>@{issue.user.login}</i> Opened: <div style="margin-top: 10px">{issue.body}</div>
{canLoadComments && <button onClick={loadComments}>Load Comments</button>}
{comments.map(comment => <div>{comment.text}</div>)}
</div>
);
};
Finally, we want to set up communication to the controller. NotebookController.onDidReceiveMessage
method is called when a renderer posts a message using the global postKernelMessage
function. To implement this method, attach to onDidReceiveMessage
to listen for messages:
class Controller {
// ...
constructor() {
// ...
this._controller.onDidReceiveMessage(event => {
if (event.message.command === 'comments') {
_getCommentsForIssue(event.message.issueId).then(
comments =>
this._controller.postMessage({
type: 'comments',
issueId: event.message.issueId,
comments
}),
event.editor
);
}
});
}
}
Interactive Notebooks (communicating with the extension host)
Imagine we want to add the ability to open the output item within a separate editor. To make this possible, the renderer needs to be able to send a message to the extension host, which will then launch the editor.
This would be useful in scenarios where the renderer and controller are two separate extensions.
In the package.json
of the renderer extension specify the value for requiresMessaging
as optional
which allows your renderer to work in both situations when it has and doesn't have access to the extension host.
{
"activationEvents": ["...."],
"contributes": {
...
"notebookRenderer": [
{
"id": "output-editor-renderer",
"displayName": "Output Editor Renderer",
"entrypoint": "./out/renderer.js",
"mimeTypes": [...],
"requiresMessaging": "optional"
}
]
}
}
The possible values for requiresMessaging
include:
always
: Messaging is required. The renderer will only be used when it's part of an extension that can be run in an extension host.optional
: The renderer is better with messaging when the extension host is available, but it's not required to install and run the renderer.never
: The renderer does not require messaging.
The last two options are preferred, as this ensures the portability of renderer extensions to other contexts where the extension host might not necessarily be available.
The renderer script file can setup communications as follows:
import { ActivationFunction } from 'vscode-notebook-renderer';
export const activate: ActivationFunction = (context) => ({
renderOutputItem(data, element) {
// Render the output using the output `data`
....
// The availability of messaging depends on the value in `requiresMessaging`
if (!context.postMessage){
return;
}
// Upon some user action in the output (such as clicking a button),
// send a message to the extension host requesting the launch of the editor.
document.querySelector('#openEditor').addEventListener('click', () => {
context.postMessage({
request: 'showEditor',
data: '<custom data>'
})
});
}
});
And then you can consume that message in the extension host as follows:
const messageChannel = notebooks.createRendererMessaging('output-editor-renderer');
messageChannel.onDidReceiveMessage(e => {
if (e.message.request === 'showEditor') {
// Launch the editor for the output identified by `e.message.data`
}
});
Note:
- To ensure your extension is running in the extension host before messages are delivered, add
onRenderer:<your renderer id>
to youractivationEvents
and set up communication in your extension'sactivate
function. - Not all messages sent by the renderer extension to the extension host are guaranteed to be delivered. A user could close the notebook before messages from the renderer are delivered.
Supporting debugging
For some controllers, such as those that implement a programming language, it can be desirable to allow debugging a cell's execution. To add debugging support, a notebook kernel can implement a debug adapter, either by directly implementing the debug adapter protocol (DAP), or by delegating and transforming the protocol to an existing notebook debugger (as done in the 'vscode-simple-jupyter-notebook' sample). A much simpler approach is to use an existing unmodified debug extension and transform the DAP for notebook needs on the fly (as done in 'vscode-nodebook').
Samples:
- vscode-nodebook: Node.js notebook with debugging support provided by VS Code's built-in JavaScript debugger and some simple protocol transformations
- vscode-simple-jupyter-notebook: Jupyter notebook with debugging support provided by the existing Xeus debugger

Markdown Extension
Markdown extensions allow you to extend and enhance Visual Studio Code's built-in Markdown preview. This includes changing the look of the preview or adding support for new Markdown syntax.
Changing the look of the Markdown preview with CSS
Extensions can contribute CSS to change the look or layout of the Markdown preview. Stylesheets are registered using the markdown.previewStyles
Contribution Point in the extension's package.json
:
"contributes": {
"markdown.previewStyles": [
"./style.css"
]
}
"markdown.previewStyles"
is a list of files relative to the extension's root folder.
Contributed styles are added after the built-in Markdown preview styles but before a user's "markdown.styles"
.
The Markdown Preview GitHub Styling extension is a good example that demonstrates using a stylesheet to make the Markdown preview look like GitHub's rendered Markdown. You can review the extension's source code on GitHub.
Adding support for new syntax with markdown-it plugins
The VS Code Markdown preview supports the CommonMark specification. Extensions can add support for additional Markdown syntax by contributing a markdown-it plugin.
To contribute a markdown-it plugin, first add a "markdown.markdownItPlugins"
contribution in your extension's package.json
:
"contributes": {
"markdown.markdownItPlugins": true
}
Then, in the extension's main activation
function, return an object with a function named extendMarkdownIt
. This function takes the current markdown-it instance and must return a new markdown-it instance:
import * as vscode from 'vscode';
export function activate(context: vscode.ExtensionContext) {
return {
extendMarkdownIt(md: any) {
return md.use(require('markdown-it-emoji'));
}
};
}
To contribute multiple markdown-it plugins, return multiple use
statements chained together:
return md.use(require('markdown-it-emoji')).use(require('markdown-it-hashtag'));
Extensions that contribute markdown-it plugins are activated lazily, when a Markdown preview is shown for the first time.
The markdown-emoji extension demonstrates using a markdown-it plugin to add emoji support to the markdown preview. You can review the Emoji extension's source code on GitHub.
You may also want to review:
- Guidelines for markdown-it plugin developers
- Existing markdown-it plugins
Adding advanced functionality with scripts
For advanced functionality, extensions may contribute scripts that are executed inside of the Markdown preview.
"contributes": {
"markdown.previewScripts": [
"./main.js"
]
}
Contributed scripts are loaded asynchronously and reloaded on every content change.
The Markdown Preview Mermaid Support extension demonstrates using scripts to add Mermaid diagrams and flowchart support to the markdown preview. You can review the Mermaid extension's source code on GitHub.

Code with poor readability is difficult for other developers to maintain and extend. Copilot Chat can help in a number of ways. For example, by:
- Suggesting improvements to variable names
- Avoiding sequential conditional checks
- Reducing nested logic
- Splitting large methods into smaller, more readable ones
Documenting your code is another way to improve the maintainability of your code. For information about using Copilot Chat to help you add useful comments to your code, see the example prompts in Documenting code.
Note
The responses shown in this article are examples. Copilot Chat responses are non-deterministic, so you may get different responses from the ones shown here.
Improving variable names
Descriptive variable names and parameter names make it easier to understand their purpose.
Example scenario
This JavaScript code logs a message about a person's age to the console. The abstract parameter names make it difficult to understand the purpose of the code.
function logPersonsAge(a, b, c) {
if (c) {
console.log(a + " is " + b + " years old.");
} else {
console.log(a + " does not want to reveal their age.");
}
}
Example prompt
In the editor, select the function you want to change, then ask Copilot Chat:
Improve the variable names in this function
function logPersonsAge(a, b, c) { if (c) { console.log(a + " is " + b + " years old."); } else { console.log(a + " does not want to reveal their age."); } } Improve the variable names in this function
Improve the variable names in this function
Example response
Copilot suggests descriptive variable names.
function logPersonAge(name, age, revealAge) {
if (revealAge) {
console.log(name + " is " + age + " years old.");
} else {
console.log(name + " does not want to reveal their age.");
}
}
Avoiding sequential conditional checks
if...else
chains can be difficult to read, especially when they are long.
Example scenario
This Python code prints the sound that various animals make, if defined, or "Unknown animal" if the animal type is not recognized. However, the chain of if...else
statements makes the code inefficient and cumbersome.
class Animal:
def speak(self):
pass
class Dog(Animal):
def speak(self):
return "Woof!"
class Cat(Animal):
def speak(self):
return "Meow!"
class Bird(Animal):
def speak(self):
return "Tweet!"
def animal_sound(animal_type):
if animal_type == "dog":
return Dog().speak()
elif animal_type == "cat":
return Cat().speak()
elif animal_type == "bird":
return Bird().speak()
else:
return "Unknown animal"
print(animal_sound("dog"))
print(animal_sound("cat"))
print(animal_sound("bird"))
print(animal_sound("fish"))
Example prompt
Simplify this code. Avoid using if/else chains but retain all function return values.
class Animal: def speak(self): pass class Dog(Animal): def speak(self): return "Woof!" class Cat(Animal): def speak(self): return "Meow!" class Bird(Animal): def speak(self): return "Tweet!" def animal_sound(animal_type): if animal_type == "dog": return Dog().speak() elif animal_type == "cat": return Cat().speak() elif animal_type == "bird": return Bird().speak() else: return "Unknown animal" print(animal_sound("dog")) print(animal_sound("cat")) print(animal_sound("bird")) print(animal_sound("fish")) Simplify this code. Avoid using if/else chains but retain all function return values.
Simplify this code. Avoid using if/else chains but retain all function return values.
Example response
Copilot suggests using a dictionary to map the animal types to their corresponding classes.
class Animal:
def speak(self):
pass
class Dog(Animal):
def speak(self):
return "Woof!"
class Cat(Animal):
def speak(self):
return "Meow!"
class Bird(Animal):
def speak(self):
return "Tweet!"
def animal_sound(animal_type):
animals = {
"dog": Dog,
"cat": Cat,
"bird": Bird
}
animal_class = animals.get(animal_type, Animal)
return animal_class().speak() if animal_class != Animal else "Unknown animal"
print(animal_sound("dog"))
print(animal_sound("cat"))
print(animal_sound("bird"))
print(animal_sound("fish"))
Reducing nested logic
Deeply nested structures can make the code hard to follow, making it difficult to modify or extend the logic of the code in future.
Example scenario
This Ruby code prints information about a user account based on three parameters. The use of nested if...else
statements makes the code unnecessarily complex.
def determine_access(user_role, has_permission, is_active)
if user_role == "admin"
if has_permission
if is_active
"Active admin account with full access."
else
"Inactive admin account."
end
else
"Admin account lacks necessary permissions."
end
else
"Access denied."
end
end
puts determine_access("admin", true, true)
puts determine_access("admin", true, false)
puts determine_access("admin", false, true)
puts determine_access("user", true, true)
Example prompt
Rewrite this code to avoid the nested if/else statements
def determine_access(user_role, has_permission, is_active) if user_role == "admin" if has_permission if is_active "Active admin account with full access." else "Inactive admin account." end else "Admin account lacks necessary permissions." end else "Access denied." end end puts determine_access("admin", true, true) puts determine_access("admin", true, false) puts determine_access("admin", false, true) puts determine_access("user", true, true) Rewrite this code to avoid the nested if/else statements
Rewrite this code to avoid the nested if/else statements
Example response
Copilot suggests using guard clauses to handle the conditions early and return the appropriate messages.
def determine_access(user_role, has_permission, is_active)
return "Access denied." unless user_role == "admin"
return "Admin account lacks necessary permissions." unless has_permission
return "Inactive admin account." unless is_active
"Active admin account with full access."
end
puts determine_access("admin", true, true)
puts determine_access("admin", true, false)
puts determine_access("admin", false, true)
puts determine_access("user", true, true)
Splitting up large methods
It can be difficult to grasp exactly what a method or function does if it is too long, making it difficult to maintain. Methods or functions that perform multiple tasks may not be reusable in other contexts. It may also be difficult to test each task in isolation.
Example scenario
This Java method processes a customer order and prints a message. It performs multiple tasks in a single method.
public void processOrder(Order order) {
if (order == null || order.getItems().isEmpty()) {
throw new IllegalArgumentException("Order is invalid.");
}
double totalPrice = 0.0;
for (Item item : order.getItems()) {
totalPrice += item.getPrice() * item.getQuantity();
}
order.setTotalPrice(totalPrice);
if (totalPrice > 0) {
order.setStatus("Processed");
} else {
order.setStatus("Pending");
}
System.out.println("Order for customer " + order.getCustomerName() + " has been processed. Total price: " + totalPrice);
}
Example prompt
How could the processOrder method be refactored to be more useful and easier to maintain
public void processOrder(Order order) { if (order == null || order.getItems().isEmpty()) { throw new IllegalArgumentException("Order is invalid."); } double totalPrice = 0.0; for (Item item : order.getItems()) { totalPrice += item.getPrice() * item.getQuantity(); } order.setTotalPrice(totalPrice); if (totalPrice > 0) { order.setStatus("Processed"); } else { order.setStatus("Pending"); } System.out.println("Order for customer " + order.getCustomerName() + " has been processed. Total price: " + totalPrice); } How could the processOrder method be refactored to be more useful and easier to maintain
How could the processOrder method be refactored to be more useful and easier to maintain
Example response
Copilot suggests breaking this method down into smaller, more focused methods.
public void processOrder(Order order) {
validateOrder(order);
double totalPrice = calculateTotalPrice(order);
updateOrderStatus(order, totalPrice);
printOrderSummary(order, totalPrice);
}
private void validateOrder(Order order) {
if (order == null || order.getItems().isEmpty()) {
throw new IllegalArgumentException("Order is invalid.");
}
}
private double calculateTotalPrice(Order order) {
double totalPrice = 0.0;
for (Item item : order.getItems()) {
totalPrice += item.getPrice() * item.getQuantity();
}
order.setTotalPrice(totalPrice);
return totalPrice;
}
private void updateOrderStatus(Order order, double totalPrice) {
if (totalPrice > 0) {
order.setStatus("Processed");
} else {
order.setStatus("Pending");
}
}
private void printOrderSummary(Order order, double totalPrice) {
System.out.println("Order for customer " + order.getCustomerName() + " has been processed. Total price: " + totalPrice);
}

Code that doesn’t follow established design patterns (like Singleton, Factory, or Observer) can lead to issues like tight coupling, lack of flexibility, or duplicated code.
Copilot Chat can help you use appropriate design patterns to make your code more flexible and maintainable. For example, it can recommend converting repetitive instantiations into a Factory pattern, or using the Observer pattern to decouple tightly connected classes.
Note
The responses described in this article are examples. Copilot Chat responses are non-deterministic, so you may get different responses from the ones shown here.
Example scenario
This JavaScript code creates three Person
objects, each with name
and age
properties. It then uses the name of a person to retrieve and print their age.
class Person {
constructor(name, age) {
this.name = name;
this.age = age;
}
}
var people = {};
function addPerson(name, age) {
people[name] = new Person(name, age);
}
function getAge(name) {
if (people[name]) {
console.log(name + " is " + people[name].age + " years old.");
} else {
console.log("Person not found.");
}
}
addPerson("Ana", 30);
addPerson("Mario", 25);
addPerson("Louise", 40);
getAge("Mario");
Example prompt 1
What design patterns could improve this code? Don't show me code examples.
